# Response formatting
# =========================================================================

def jsonrpc_result(msg_id: Any, result: dict) -> bytes:
    """Format a successful JSON-RPC 2.0 response."""
    return _dumps({
        "id": msg_id,
        "jsonrpc": "2.0",
        "result": result,
    })


def jsonrpc_error(msg_id: Any, code: int, message: str,
                  data: Optional[dict] = None) -> bytes:
